'use strict';
// Writes js/default-config.js from a config file so the tracker starts with a
// built-in configuration and needs no file chooser. Run with:
//   node tools/default-config.js [path/to/config.json]     (default: ./config.json)
const fs = require('fs');
const path = require('path');

const source = process.argv[2] || path.join(__dirname, '..', 'config.json');
const target = path.join(__dirname, '..', 'js', 'default-config.js');
const config = JSON.parse(fs.readFileSync(source, 'utf8'));
for (const key of ['light-world', 'dark-world', 'entranceMap', 'settings']) {
	if (!config[key]) throw new Error(`${source} has no "${key}" section`);
}
delete config.coop;
if (config.settings) { delete config.settings.spoiler; delete config.settings.spoilerText; }
const lines = [
	"'use strict';",
	'',
	'// Generated by tools/default-config.js from ' + path.basename(source) + ': the built-in',
	'// configuration used on first start and whenever no defaults are stored yet.',
	'const DEFAULT_CONFIG = ' + JSON.stringify(config) + ';',
	'',
];
fs.writeFileSync(target, lines.join('\r\n'));
console.log(`wrote ${path.relative(process.cwd(), target)} (${fs.statSync(target).size} bytes)`);
